(172, 11, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Bạn là sinh viên phải không?', '/uploads/audios/sentences/anata-wa-gakusei-desu-ka.mp3', '/uploads/images/vocab/gakusei.png', '{"romaji": "Anata wa gakusei desu ka.", "vn": "Bạn là sinh viên phải không?", "jp": "あなたはがくせいですか。", "glossary": {"あなた": {"r": "anata", "v": "bạn"}, "がくせい": {"r": "gakusei", "v": "học sinh, sinh viên"}}}'),
