(596, 37, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Bây giờ là 7 giờ rưỡi.', '/uploads/audios/sentences/shichiji-han-desu.mp3', '/uploads/images/vocab/shichiji.png', '{"romaji": "Shichiji han desu.", "vn": "Bây giờ là 7 giờ rưỡi.", "jp": "しちじはんです。", "glossary": {"しちじ": {"r": "shichiji", "v": "7 giờ (bất quy tắc)"}, "はん": {"r": "han", "v": "rưỡi"}}}'),
(597, 37, 'TRANSLATE_TO_VN', 'Câu 「しちじはんです。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Shichiji han desu.", "jp": "しちじはんです。", "vn": "Bây giờ là 7 giờ rưỡi.", "teachAudio": "/uploads/audios/sentences/shichiji-han-desu.mp3", "glossary": {"しちじ": {"r": "shichiji", "v": "7 giờ (bất quy tắc)"}, "はん": {"r": "han", "v": "rưỡi"}}}'),
