(1570, 99, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Bạn vất vả rồi. Cố lên nhé.', '/uploads/audios/sentences/otsukaresama-desu-ganbatte.mp3', '/uploads/images/vocab/otsukaresama-desu.png', '{"romaji": "Otsukaresama desu. Ganbatte.", "vn": "Bạn vất vả rồi. Cố lên nhé.", "jp": "おつかれさまです。がんばって。", "glossary": {"おつかれさまです": {"r": "otsukaresama desu", "v": "bạn vất vả rồi"}, "がんばって": {"r": "ganbatte", "v": "cố lên nhé"}}}'),
(1571, 99, 'TRANSLATE_TO_VN', 'Câu 「どうもありがとうございます。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Doumo arigatou gozaimasu.", "jp": "どうもありがとうございます。", "vn": "Cảm ơn bạn rất nhiều.", "teachAudio": "/uploads/audios/sentences/doumo-arigatou-gozaimasu.mp3", "glossary": {"ありがとうございます": {"r": "arigatou gozaimasu", "v": "cảm ơn (lịch sự)"}, "ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}}}'),
(1572, 99, 'TRANSLATE_TO_VN', '「いってらっしゃい」 (itterasshai) nghĩa là gì?', NULL, NULL, '{"kana": "いってらっしゃい", "romaji": "itterasshai", "vn": "đi rồi về nhé", "teachAudio": "/uploads/audios/words/itterasshai.mp3", "glossary": {"いってらっしゃい": {"r": "itterasshai", "v": "đi rồi về nhé"}}}'),
(1573, 99, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/otsukaresama-desu.mp3', NULL, '{"romaji": "otsukaresama desu", "vn": "bạn vất vả rồi", "glossary": {"おはよう": {"r": "ohayou", "v": "chào buổi sáng (thân mật)"}, "ありがとうございます": {"r": "arigatou gozaimasu", "v": "cảm ơn (lịch sự)"}, "ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}, "すみません": {"r": "sumimasen", "v": "xin lỗi / cho hỏi"}, "おつかれさまです": {"r": "otsukaresama desu", "v": "bạn vất vả rồi"}}}'),
(1574, 99, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Rất hân hạnh, mong được giúp đỡ.', '/uploads/audios/sentences/hajimemashite-yoroshiku-onegaishimasu.mp3', '/uploads/images/vocab/yoroshiku-onegaishimasu.png', '{"romaji": "Hajimemashite, yoroshiku onegaishimasu.", "vn": "Rất hân hạnh, mong được giúp đỡ.", "jp": "はじめまして、よろしくおねがいします。", "glossary": {"はじめまして": {"r": "hajimemashite", "v": "rất hân hạnh được gặp"}, "よろしくおねがいします": {"r": "yoroshiku onegaishimasu", "v": "mong được giúp đỡ"}}}'),
(1575, 99, 'TRANSLATE_TO_VN', 'Câu 「みなさん、こんにちは。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Minasan, konnichiwa.", "jp": "みなさん、こんにちは。", "vn": "Xin chào mọi người.", "teachAudio": "/uploads/audios/sentences/minasan-konnichiwa.mp3", "glossary": {"こんにちは": {"r": "konnichiwa", "v": "xin chào (ban ngày)"}}}'),
(1576, 99, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: いってきます。いってらっしゃい。', '/uploads/audios/sentences/ittekimasu-itterasshai.mp3', '/uploads/images/vocab/itterasshai.png', '{"romaji": "Ittekimasu. Itterasshai.", "vn": "Con đi đây. Đi rồi về nhé.", "jp": "いってきます。いってらっしゃい。", "glossary": {"いってきます": {"r": "ittekimasu", "v": "con/tôi đi đây"}, "いってらっしゃい": {"r": "itterasshai", "v": "đi rồi về nhé"}}}'),
(1577, 99, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/tadaima.mp3', NULL, '{"romaji": "tadaima", "vn": "con/tôi về rồi", "glossary": {"こんばんは": {"r": "konbanwa", "v": "chào buổi tối"}, "ありがとう": {"r": "arigatou", "v": "cảm ơn (thân mật)"}, "すみません": {"r": "sumimasen", "v": "xin lỗi / cho hỏi"}, "ただいま": {"r": "tadaima", "v": "con/tôi về rồi"}}}'),
(1578, 100, 'TRANSLATE_TO_VN', 'Câu 「あさくすりをのみます。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Asa kusuri o nomimasu.", "jp": "あさくすりをのみます。", "vn": "Buổi sáng tôi uống thuốc.", "teachAudio": "/uploads/audios/sentences/asa-kusuri-o-nomimasu.mp3", "glossary": {"の": {"r": "no", "v": "của (nối 2 danh từ)"}, "あさ": {"r": "asa", "v": "buổi sáng"}, "のみます": {"r": "nomimasu", "v": "uống"}, "みます": {"r": "mimasu", "v": "xem, nhìn"}, "を": {"r": "wo", "v": "trợ từ tân ngữ"}, "くすり": {"r": "kusuri", "v": "thuốc"}}}'),
(1579, 100, 'TRANSLATE_TO_VN', '「やすんでください」 (yasunde kudasai) nghĩa là gì?', NULL, NULL, '{"kana": "やすんでください", "romaji": "yasunde kudasai", "vn": "hãy nghỉ ngơi đi", "teachAudio": "/uploads/audios/words/yasunde-kudasai.mp3", "glossary": {"ください": {"r": "kudasai", "v": "cho tôi xin…"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "やすんでください": {"r": "yasunde kudasai", "v": "hãy nghỉ ngơi đi"}}}'),
(1580, 100, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: きょうはうちでやすんでください。', '/uploads/audios/sentences/kyou-wa-uchi-de-yasunde-kudasai.mp3', '/uploads/images/vocab/yasunde-kudasai.png', '{"romaji": "Kyou wa uchi de yasunde kudasai.", "vn": "Hôm nay hãy nghỉ ở nhà nhé.", "jp": "きょうはうちでやすんでください。", "glossary": {"ください": {"r": "kudasai", "v": "cho tôi xin…"}, "きょう": {"r": "kyou", "v": "hôm nay"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "うち": {"r": "uchi", "v": "nhà (của mình)"}, "やすんでください": {"r": "yasunde kudasai", "v": "hãy nghỉ ngơi đi"}}}'),
(1581, 100, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/mainichi-nomimasu.mp3', NULL, '{"romaji": "mainichi nomimasu", "vn": "uống mỗi ngày", "glossary": {"の": {"r": "no", "v": "của (nối 2 danh từ)"}, "に": {"r": "ni", "v": "số 2"}, "まいにち": {"r": "mainichi", "v": "hằng ngày"}, "のみます": {"r": "nomimasu", "v": "uống"}, "みます": {"r": "mimasu", "v": "xem, nhìn"}, "め": {"r": "me", "v": "mắt"}, "みみ": {"r": "mimi", "v": "tai"}, "いたい": {"r": "itai", "v": "đau"}, "まいにちのみます": {"r": "mainichi nomimasu", "v": "uống mỗi ngày"}}}'),
(1582, 100, 'TRANSLATE_TO_JP', '「cảm, cảm lạnh」 tiếng Nhật nói thế nào?', NULL, '/uploads/images/vocab/kaze.png', '{"kana": "かぜ", "romaji": "kaze", "vn": "cảm, cảm lạnh", "teachAudio": "/uploads/audios/words/kaze.mp3", "glossary": {"なか": {"r": "naka", "v": "bên trong"}, "くち": {"r": "kuchi", "v": "miệng"}, "みみ": {"r": "mimi", "v": "tai"}, "おなか": {"r": "onaka", "v": "bụng"}, "かぜ": {"r": "kaze", "v": "cảm, cảm lạnh"}}}'),
(1583, 100, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/dou-shimashita-ka.mp3', NULL, '{"romaji": "dou shimashita ka", "vn": "bạn bị làm sao thế?", "glossary": {"した": {"r": "shita", "v": "phía dưới"}, "なか": {"r": "naka", "v": "bên trong"}, "ました": {"r": "mashita", "v": "đã… (quá khứ)"}, "くち": {"r": "kuchi", "v": "miệng"}, "おなか": {"r": "onaka", "v": "bụng"}, "いたい": {"r": "itai", "v": "đau"}, "どうしましたか": {"r": "dou shimashita ka", "v": "bạn bị làm sao thế?"}}}'),
(1584, 100, 'TRANSLATE_TO_VN', '「きもちがいい」 (kimochi ga ii) nghĩa là gì?', NULL, NULL, '{"kana": "きもちがいい", "romaji": "kimochi ga ii", "vn": "thấy dễ chịu", "teachAudio": "/uploads/audios/words/kimochi-ga-ii.mp3", "glossary": {"が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "いい": {"r": "ii", "v": "tốt"}, "きもちがいい": {"r": "kimochi ga ii", "v": "thấy dễ chịu"}}}'),
(1585, 100, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/nemui.mp3', NULL, '{"romaji": "nemui", "vn": "buồn ngủ", "glossary": {"なか": {"r": "naka", "v": "bên trong"}, "て": {"r": "te", "v": "tay"}, "あたま": {"r": "atama", "v": "đầu"}, "おなか": {"r": "onaka", "v": "bụng"}, "ねむい": {"r": "nemui", "v": "buồn ngủ"}}}'),
