(1587, 100, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/yasunde-kudasai.mp3', NULL, '{"romaji": "yasunde kudasai", "vn": "hãy nghỉ ngơi đi", "glossary": {"ください": {"r": "kudasai", "v": "cho tôi xin…"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "はな": {"r": "hana", "v": "mũi"}, "て": {"r": "te", "v": "tay"}, "いたい": {"r": "itai", "v": "đau"}, "やすんでください": {"r": "yasunde kudasai", "v": "hãy nghỉ ngơi đi"}}}'),
(1588, 100, 'TRANSLATE_TO_VN', '「まいにちのみます」 (mainichi nomimasu) nghĩa là gì?', NULL, NULL, '{"kana": "まいにちのみます", "romaji": "mainichi nomimasu", "vn": "uống mỗi ngày", "teachAudio": "/uploads/audios/words/mainichi-nomimasu.mp3", "glossary": {"の": {"r": "no", "v": "của (nối 2 danh từ)"}, "に": {"r": "ni", "v": "số 2"}, "まいにち": {"r": "mainichi", "v": "hằng ngày"}, "のみます": {"r": "nomimasu", "v": "uống"}, "みます": {"r": "mimasu", "v": "xem, nhìn"}, "まいにちのみます": {"r": "mainichi nomimasu", "v": "uống mỗi ngày"}}}'),
(1589, 100, 'TRANSLATE_TO_VN', 'Câu 「あさはいつもねむいです。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Asa wa itsumo nemui desu.", "jp": "あさはいつもねむいです。", "vn": "Buổi sáng lúc nào tôi cũng buồn ngủ.", "teachAudio": "/uploads/audios/sentences/asa-wa-itsumo-nemui-desu.mp3", "glossary": {"はい": {"r": "hai", "v": "vâng, đúng vậy"}, "あさ": {"r": "asa", "v": "buổi sáng"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "いつも": {"r": "itsumo", "v": "luôn luôn"}, "ねむい": {"r": "nemui", "v": "buồn ngủ"}}}'),
(1590, 100, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Bố tôi chân dài.', '/uploads/audios/sentences/otousan-wa-ashi-ga-nagai-desu.mp3', '/uploads/images/vocab/ashi.png', '{"romaji": "Otousan wa ashi ga nagai desu.", "vn": "Bố tôi chân dài.", "jp": "おとうさんはあしがながいです。", "glossary": {"さん": {"r": "san", "v": "số 3"}, "が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "おとうさん": {"r": "otousan", "v": "bố (của bạn)"}, "ながい": {"r": "nagai", "v": "dài"}, "あし": {"r": "ashi", "v": "chân"}}}'),
(1591, 100, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/netsu.mp3', NULL, '{"romaji": "netsu", "vn": "sốt", "glossary": {"なか": {"r": "naka", "v": "bên trong"}, "て": {"r": "te", "v": "tay"}, "おなか": {"r": "onaka", "v": "bụng"}, "いたい": {"r": "itai", "v": "đau"}, "ねつ": {"r": "netsu", "v": "sốt"}}}'),
